&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Other qualities&amp;nbsp;you’ll&amp;nbsp;need to be a fit for this role include:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
